parameters.jsCode:
const webhookData = $('Status Webhook').first().json.body;

for (const item of $input.all()) {
  item.json.order_number = webhookData.order_number;
  item.json.status = webhookData.status;
  item.json.cancel_reason = webhookData.cancel_reason || null;
}

return $input.all();

for (const item of $input.all()) {
  const order = item.json;
  let msg = "";
  let skip = false;

  if (Array.isArray(order) && order.length > 0) {
    Object.assign(order, order[0]);
  }

  switch(order.status) {
    case 'preparing':
      msg = `Your Pabbas order #${order.order_number} is now being prepared. 👨‍🍳✨
We're getting everything ready for you!`;
      break;

    case 'ready_for_pickup':
      msg = `Your Pabbas order #${order.order_number} is ready for pickup! 🎉
You can collect it at the counter whenever you're ready. 😊`;
      break;

    case 'out_for_delivery':
      msg = `Your Pabbas order #${order.order_number} is on its way! 🛵💨
It won't be long now. Enjoy your treats! 🍨❤️`;
      break;

    case 'delivered':
      msg = `Your Pabbas order #${order.order_number} has been delivered. 🎉
We hope you enjoy your order! Thank you for choosing Pabbas. ❤️`;
      break;

    case 'cancelled':
      const cancelReason = order.cancel_reason
        ? `\nReason: ${order.cancel_reason}`
        : '';

      msg = `Your Pabbas order #${order.order_number} has been cancelled.${cancelReason}`;
      break;

    default:
      skip = true;
  }

  item.json.phone = order.customer_phone;
  item.json.message = msg;
  item.json.skip = skip;
}

return $input.all();

