parameters.jsCode:
const item = $input.first();
const body = item.json.body || item.json;

const order_number = body.order_number || '';
const customer_phone = body.customer_phone || '';
const customer_name = body.customer_name || 'Valued Customer';
const order_type = body.order_type || 'delivery';
const items = body.items || [];
const total = body.total || 0;

return [{
  json: {
    order_number,
    customer_phone,
    customer_name,
    order_type,
    items,
    total
  }
}];

const item = $input.first();
const o = item.json;

let itemLines = '';
if (Array.isArray(o.items) && o.items.length > 0) {
  itemLines = o.items
    .map(i => `• ${i.item_name} x${i.quantity}`)
    .join('\n');
} else {
  itemLines = '• (see order details)';
}

const typeLabel = o.order_type === 'dine-in' ? 'Dine-in' :
                  o.order_type === 'takeaway' ? 'Takeaway' : 'Delivery';

const msg = `Hi ${o.customer_name}! 👋

We've received your Pabbas ${typeLabel} order #${o.order_number}.

Your order:
${itemLines}

Total: ₹${o.total}

We'll keep you updated here on WhatsApp. Thank you!`;

return [{
  json: {
    phone: o.customer_phone,
    message: msg,
    skip: !o.customer_phone
  }
}];

